class JitifyCache(object):
    r"""
    Load RTC kernels from in-memory or on-disk cache if an appropriate copy already exists
    If not, compile and add to both caches
    Loading an RTC kernel from cache is significantly faster than compiling.

    This class should sit between FLAMEGPU and Jitify
    """

    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")

    def __init__(self, *args, **kwargs):
        raise AttributeError("No constructor defined")
    __repr__ = _swig_repr

    def useMemoryCache(self, *args):
        r"""
        *Overload 1:*

        Used to configure whether the in-memory cache is used
        Defaults to true

        |

        *Overload 2:*

        Returns whether use of the in-memory cache is currently enabled
        """
        return _pyflamegpu.JitifyCache_useMemoryCache(self, *args)

    def clearMemoryCache(self):
        r"""
        Clears the in-memory cache
        All kernels loaded after this will need to come from the on-disk cache or be compiled
        """
        return _pyflamegpu.JitifyCache_clearMemoryCache(self)

    def useDiskCache(self, *args):
        r"""
        *Overload 1:*

        Used to configure whether the on-disk cache is used
        Defaults to true
        Notes: If disk cache is disabled both importing and exporting cache files to disk will be disabled

        |

        *Overload 2:*

        Returns whether use of the on-disk cache is currently enabled
        Notes: If disk cache is disabled both importing and exporting cache files to disk will be disabled
        """
        return _pyflamegpu.JitifyCache_useDiskCache(self, *args)

    @staticmethod
    def clearDiskCache():
        r"""
        Clears the in-memory cache
        All kernels loaded after this will need to come from the on-disk cache or be compiled
        Notes: Will only clear the cache files used by the current build (debug or release)
        """
        return _pyflamegpu.JitifyCache_clearDiskCache()

    @staticmethod
    def getInstance():
        r"""Returns the EnvironmentManager singleton instance"""
        return _pyflamegpu.JitifyCache_getInstance()
    __swig_destroy__ = _pyflamegpu.delete_JitifyCache

# Register JitifyCache in _pyflamegpu:
_pyflamegpu.JitifyCache_swigregister(JitifyCache)
